function OneThirdCertificate(p[1..n]):
    if n = 0: return False
    for i <- 1 to n:
        if p[i] < 1/2: return False
    winners <- count of i with p[i] > 1/2
    return winners >= n / 3

function FractionBoundFloor(p[1..n], eps):
    if n = 0: return (0, 0)
    good <- count of i with p[i] >= 1/2 + eps
    alpha <- good / n
    floor <- alpha * n * (2 * eps)
    return (alpha, floor)
